G=load()
def solve(t, fc):
    H=len(t);W=len(t[0]);bg=t[0][0]
    fr=[(r,c) for r in range(H) for c in range(W) if t[r][c]==fc]
    r0=min(r for r,c in fr);r1=max(r for r,c in fr);c0=min(c for r,c in fr);c1=max(c for r,c in fr)
    extra=[(r,c,t[r][c]) for r in range(H) for c in range(W) if t[r][c] not in (bg,fc)]
    out=[row[:] for row in t]
    for r,c,v in extra:
        nr = r1+1 if r<(r0+r1)/2 else r0-1
        nc = c1+1 if c<(c0+c1)/2 else c0-1
        out[nr][nc]=v; out[r][c]=bg
    return out
